import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Candidate-only static call census. A located call is not a proved bug or a passed lifecycle test. */
public final class SourceLifetimeLookupRefs {
 static final String P="local/lito381/server/";
 static String kind(MethodInsnNode c){String owner=c.owner.startsWith(P)?c.owner.substring(P.length()):"";return switch(owner+"."+c.name){case "NativePlayerLifetime.of"->"creating-lifetime-lookup";case "NativePlayerVitalCompletions.reserve"->"original-peer-receipt-reserve";case "CombatPoisonAtomic.status"->"creating-status-lookup";case "NativeRoleToken.of"->"creating-role-lookup";case "NativeCombatAttacker.token"->"token-call-boolean-argument-needs-review";case "NativeSourceControlledDisplay.token"->"creating-controlled-life-wrapper";case "NativeSourceMonsterHp.life"->"creating-natural-life-wrapper";case "NativeDeItemApplication.publicationOwner"->"creating-item-publication-owner";default->null;};}
 public static void main(String[]args)throws Exception{var rows=new ArrayList<String>();rows.add("kind\tcaller_owner\tcaller_method\tcaller_descriptor\tinstruction_index\tcallee_owner\tcallee_method\tcallee_descriptor\tcaller_has_monitorenter\tcaller_is_synchronized\tcaller_has_explicit_action_lock_or_pair_call");var totals=new TreeMap<String,Integer>();int owners=0,methods=0;try(var jar=new JarFile(args[0])){for(var entry:Collections.list(jar.entries())){if(!entry.getName().startsWith(P)||!entry.getName().endsWith(".class"))continue;var node=new ClassNode();new ClassReader(jar.getInputStream(entry).readAllBytes()).accept(node,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);owners++;for(var method:node.methods){methods++;boolean monitors=false,locks=false;for(var n:method.instructions){if(n.getOpcode()==MONITORENTER)monitors=true;if(n instanceof MethodInsnNode c&&(c.owner.equals("java/util/concurrent/locks/ReentrantLock")||c.name.equals("runPairOrdered")||c.name.equals("commitPair")||c.name.equals("runPair")))locks=true;}int index=0;for(var n:method.instructions){if(n instanceof MethodInsnNode call){String kind=kind(call);if(kind!=null){totals.merge(kind,1,Integer::sum);rows.add(String.join("\t",kind,node.name,method.name,method.desc,Integer.toString(index),call.owner,call.name,call.desc,Boolean.toString(monitors),Boolean.toString((method.access&ACC_SYNCHRONIZED)!=0),Boolean.toString(locks)));}}index++;}}}}Files.write(Path.of(args[1]),rows);System.out.println("PASS read-only static lifetime lookup census; owners="+owners+", methods="+methods+", call-sites="+(rows.size()-1)+", kinds="+totals+"; phase/first-admission/wait/initializer/final-IO semantics remain unqualified");}
}
